const input = $input.first().json;
const body = input.body || input;

const errors = [];

if (!body.recipe) {
  errors.push('Missing required parameter: recipe');
}

if (!body.user_id && !body.discord_user_id) {
  errors.push('Missing required parameter: user_id or discord_user_id');
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  }];
}

const recipe = body.recipe;

// Build text for embedding
const embeddingText = [
  recipe.title || '',
  recipe.description || '',
  (recipe.tags || []).join(' '),
  (recipe.ingredients || []).map(i => i.name).join(' ')
].join(' ').trim();

return [{
  json: {
    valid: true,
    recipe,
    embedding_text: embeddingText,
    user_id: body.user_id || body.discord_user_id,
    store_embedding: body.store_embedding !== false,
    llm_metadata: body.llm_metadata || {},
    api_url: body.api_url || process.env.RECIPES_API_URL || 'http://localhost:8000',
    qdrant_url: body.qdrant_url || process.env.QDRANT_URL || 'http://localhost:6333',
    qdrant_api_key: body.qdrant_api_key || process.env.QDRANT_API_KEY,
    openai_api_key: body.openai_api_key || process.env.OPENAI_API_KEY,
    collection: 'recipes'
  }
}];

const input = $input.first().json;
const prevData = $('Validate Input').first().json;

if (input.error) {
  return [{
    json: {
      ...prevData,
      embedding: null,
      embedding_error: input.error.message
    }
  }];
}

const embedding = input.data?.[0]?.embedding;

return [{
  json: {
    ...prevData,
    embedding,
    point_id: 'rec_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9)
  }
}];

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const qdrantData = $('Prepare Qdrant').first().json;

try {
  if (input.error) {
    return [{
      json: {
        success: false,
        error: {
          code: input.error.status || 500,
          message: input.error.message || 'API save failed',
          status: 'API_ERROR'
        },
        meta: { provider: 'api' }
      }
    }];
  }

  return [{
    json: {
      success: true,
      data: {
        recipe_id: input.data?.id || input.id,
        stored_in_qdrant: !!qdrantData.embedding,
        qdrant_point_id: qdrantData.point_id || null,
        recipe: prevData.recipe
      },
      meta: {
        provider: 'api+qdrant',
        api_response: input
      }
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to process save: ' + e.message,
        status: 'PROCESS_ERROR'
      },
      meta: { provider: 'api' }
    }
  }];
}
